param([ValidateSet('build','selftest','capture')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-denominator-output-budget-20260913';$seed='D:\projects\AIMA-public-selective-qk-probability-20260913';$sha='a25b1c3074436b6d4a3d41188af9a2351777daa6';$bundle='D:\projects\denominator-output-budget-a25b1c3.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '540e60153f17be49272ca4084a726ee439bf7bd2795e806f025832b274c55a79'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\selective-qk';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\selective_qk_selftest.cpp';$exe=Join-Path $build 'selective-qk.exe'
$sourceInputs=@();$sourceFiles=@($source,(Join-Path $repo 'native\providers\ck_fmha\blackwell_attention.h'),(Join-Path $repo 'native\providers\ck_fmha\selective_qk.h'));foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn')){$sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})}
foreach($file in $sourceFiles){$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; selective QK component executable build';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Bound native QK, repair possible prefix maxima and BF16 probability boundaries, refine denominator contributors and fall back by row. Original exact scores and external GB10 output are comparison-only. The strict comparison uses canonical PV for every cell. The experimental runtime helper uses native PV plus exact replay with approximate denominator; compare it against canonical PV at that same denominator. Choose denominator refinement work from output BF16 margins while retaining strict final interval checks and exact-row fallback. No product token acceptance or TTFT is measured'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$timeout=180
 $exp2='D:\projects\sm121-exp2-interpolated-b5752a88.bin';$rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 $tableInputs=@(@{file=$exp2;sha256='b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'},@{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'})
 foreach($file in $tableInputs){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Validated table changed'}}
 $spec.arguments=@('--selftest',$exp2,$rcp);$spec.input_files=$tableInputs;$spec.model='none;35 generated finite Q/K/V cases with causal tails, cancellation, zero, subnormal and exponent spread'
 $spec.baseline_scores_are_compute_input=$false;$spec.external_reference_is_compute_input=$false
 if($Action -eq 'capture'){
  $capRoot='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
  $q=Join-Path $capRoot 'layer3-full-full_attention_q_norm_rope-bf16.bin';$k=Join-Path $capRoot 'layer3-full-full_attention_k_norm_rope-bf16.bin'
  $v=Join-Path $capRoot 'layer3-full-full_attention_v_projection-bf16.bin'
  $reference='D:\projects\full-attention-context-gb10-08734309.bin'
  $exp2='D:\projects\sm121-exp2-interpolated-b5752a88.bin';$rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
  $sources=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'},
    @{file=$v;sha256='bd95f94c94ea0606c94b6d98548a672e78479bf6df2d7ace08f3797a85907e80'},@{file=$reference;sha256='f3d9b30a1e70f97a5510a0242006e91e0754207bb8e437cdf46d777bfb6fed33'},
    @{file=$exp2;sha256='b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'},@{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'})
  foreach($file in $sources){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Original QK capture changed'}}
  $spec.input_files=$sources;$spec.arguments=@($q,$k,$v,$reference,$exp2,$rcp)
  $spec.baseline_scores_are_compute_input=$false;$spec.external_reference_is_compute_input=$false
  $spec.model='D:\models\Qwen3.6-35B-A3B; captured real q7169 layer3 Q/K/V and external GB10 BF16 context; selective QK numerical component'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
  $spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146'
  $spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
 }
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\selective-qk-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $expected=if($Action -eq 'capture'){1}else{35}
 if($reports.Count -ne $expected){throw 'Incomplete selective QK results'}
 foreach($item in $reports){
  if($item.kind -ne 'selective_qk_component' -or -not $item.redzones_pass -or -not $item.immutable_inputs -or $item.baseline_scores_are_compute_input -or $item.external_reference_is_compute_input -or $item.inference_acceptance -or $item.performance_acceptance){throw 'Invalid component scope'}
  foreach($name in @('score_bound_violations','probability_bf16_differences','alpha_bit_differences','denominator_bound_violations','final_uncertain_cells','admitted_wrong','output_bf16_differences','external_bf16_differences','nonfinite','probability_route_same_denominator_bf16_differences')){if($item.$name -ne 0){throw ('Numerical failure '+$name)}}
 }
 if($Action -eq 'capture' -and ($reports[0].tokens -ne 7169 -or $reports[0].output_cells -ne 29364224 -or -not $reports[0].external_reference)){throw 'Incomplete GB10 capture'}
}
